// Parse the Supabase Database Webhook INSERT payload
// Supabase sends: { type: 'INSERT', table: 'metadata', record: {...}, schema: 'public' }
// The record is the full new row
const body = $input.item.json.body || $input.item.json;

// Handle both direct Supabase webhook format and manual triggers
const eventType = body.type;
const record = body.record || body;  // Supabase sends record under 'record' key

const fileName = record.file_name;
const source = record.source || 'unknown';
const entryId = record.id;

// Skip if triggered from Slack — WF-02 already handles those
if (source === 'slack') {
  return {
    json: {
      skip: true,
      reason: 'slack entries handled by WF-02',
      file_name: fileName,
      source: source
    }
  };
}

if (!fileName) {
  throw new Error('No file_name in webhook payload. Keys: ' + Object.keys(body).join(', '));
}

return {
  json: {
    skip: false,
    file_name: fileName,
    entry_id: entryId,
    source: source,
    event_type: eventType || 'INSERT'
  }
};

// Skip — log and return
const d = $input.item.json;
return {
  json: {
    status: 'skipped',
    reason: d.reason,
    file_name: d.file_name,
    source: d.source
  }
};

// Small delay to allow the INSERT transaction to fully commit
// before we read the row back in crosslink_entry()
await new Promise(resolve => setTimeout(resolve, 500));
return { json: $input.item.json };

// Call Supabase crosslink_entry() RPC
const d = $input.item.json;
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdzbXR6ZHJhbXF6Y3FkeXdib3JvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NDg4NTIsImV4cCI6MjA4OTAyNDg1Mn0.0EWXPtw2A9darfVDBgCwyGw0oWGtHdKBokCf2c1Ku24';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://gsmtzdramqzcqdywboro.supabase.co/rest/v1/rpc/crosslink_entry',
  headers: {
    'apikey': ANON,
    'Authorization': 'Bearer ' + ANON,
    'Content-Type': 'application/json'
  },
  body: { p_file_name: d.file_name },
  json: true
});

return {
  json: {
    ...d,
    crosslink_result: result
  }
};

// Check if 5+ crosslinks found — trigger WF-03 notification
const d = $input.item.json;
const cl = d.crosslink_result || {};
const relatedCount = cl.related_count || 0;

if (relatedCount >= 5) {
  // Fire WF-03 async
  this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n-docker-t9sr.onrender.com/webhook/wf03-crosslink-notify',
    headers: { 'Content-Type': 'application/json' },
    body: {
      entry_id: cl.entry_id || d.entry_id,
      file_name: d.file_name,
      related_ids: cl.related_ids || [],
      related_count: relatedCount,
      tags: cl.tags || [],
      entities: cl.entities || [],
      summary: cl.summary || ''
    },
    json: true
  }).catch(() => {}); // fire-and-forget
}

return {
  json: {
    status: 'ok',
    file_name: d.file_name,
    source: d.source,
    event_type: d.event_type,
    related_count: relatedCount,
    wf03_triggered: relatedCount >= 5
  }
};
